// Claim posted to the PR:
// "This change makes the service 15% faster (one staging run)."
// Rewrite it so it survives review.

function percentile(samples, p) {
  const sorted = samples.slice().sort((a, b) => a - b);
  const idx = Math.ceil(p * sorted.length) - 1;
  // average the tail from idx onward
  let total = 0, n = 0;
  for (let i = idx; i < sorted.length; i++) { total += sorted[i]; n++; }
  return total / n;
}

